#!/usr/bin/env python3
"""Real-time Top-K Leaderboard using Bytewax."""

import argparse
import heapq
import json
import sys
from pathlib import Path
from typing import Dict, List, Optional, Tuple

import bytewax.operators as op
from bytewax.dataflow import Dataflow
from bytewax.inputs import FixedPartitionedSource, StatefulSourcePartition
from bytewax.outputs import DynamicSink, StatelessSinkPartition
from bytewax.testing import run_main
from typing_extensions import override


# Global to capture the final Top-K output.
FINAL_OUTPUT: List[Dict] = []


# ----------------------------- Input Source ----------------------------- #

class _JSONLPartition(StatefulSourcePartition):
    def __init__(self, path: str, resume_state):
        self._path = path
        self._f = open(path, "rt")
        if resume_state is not None:
            self._f.seek(resume_state)
        self._eof = False

    @override
    def next_batch(self):
        batch = []
        # Read the entire file in a single batch for simplicity; the dataflow
        # is bounded.
        for line in self._f:
            line = line.strip()
            if not line:
                continue
            batch.append(line)
        self._eof = True
        return batch

    @override
    def snapshot(self):
        return self._f.tell()

    @override
    def close(self):
        try:
            self._f.close()
        except Exception:
            pass

    @override
    def next_awake(self):
        return None


class JSONLSource(FixedPartitionedSource):
    """A source that reads a JSONL file line-by-line."""

