class _JSONLPartition(StatefulSourcePartition):
    def __init__(self, path: str, resume_state):
        self._path = path
        self._f = open(path, "rt")
        self._eof = False
        if resume_state is not None:
            self._f.seek(resume_state)

    @override
    def next_batch(self):
        batch = []
        if self._eof:
            raise StopIteration()
        # Read the entire file in a single batch for simplicity; the dataflow
        # is bounded.
        for line in self._f:
            line = line.strip()
            if not line:
                continue
            batch.append(line)
        self._eof = True
        return batch

    @override
    def snapshot(self):
        return self._f.tell()

    @override
    def close(self):
        try:
            self._f.close()
        except Exception:
            pass

    @override
    def next_awake(self):
        return None


class JSONLSource(FixedPartitionedSource):
    """A source that reads a JSONL file line-by-line."""

    def __init__(self, path: str):
        self._path = path

    @override
    def list_parts(self):
        return ["single"]

    @override
    def build_part(self, step_id, for_part, resume_state):
        return _JSONLPartition(self._path, resume_state)


# ----------------------------- Output Sink ----------------------------- #

class _CollectSinkPartition(StatelessSinkPartition):
    def __init__(self):
        self._items: List = []

    @override
    def write_batch(self, items):
        self._items.extend(items)

    @override
    def close(self):
        FINAL_OUTPUT.extend(self._items)


class CollectSink(DynamicSink):
    @override
    def build(self, step_id, worker_index, worker_count):
