    max_size: int
    state: _CollectState[V]

    @override
    def on_item(self, value: V) -> Tuple[Iterable[List[V]], bool]:
        self.state.timeout_at = self.now_getter() + self.timeout

        self.state.acc.append(value)
        if len(self.state.acc) >= self.max_size:
